-- Existing dedicated target tables only. All publication and run receipt are atomic.
BEGIN TRANSACTION;
ASSERT (SELECT COUNT(*) FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.pipeline_runs` WHERE run_id = @run_id) <= 1
  AS 'Duplicate run receipts require investigation';
ASSERT NOT EXISTS (
  SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.pipeline_runs`
  WHERE run_id = @run_id AND source_fingerprint <> @fingerprint
) AS 'Run ID already belongs to different source/code';
ASSERT NOT EXISTS (
  SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.pipeline_runs` WHERE run_id = @run_id
    AND (source_rows <> @source_rows OR clean_rows <> @clean_rows
      OR quarantined_rows <> @quarantined_rows OR quality_rows <> @quality_rows
      OR source_uri <> @source_uri OR source_generation <> @source_generation
      OR source_sha256 <> @source_sha256)
) AS 'Existing receipt metadata differs';

ASSERT (SELECT COUNT(*) FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_ledger_ce8978f61503ea9e13b8553698b719af`) = @source_rows AS 'Source count mismatch';
ASSERT (SELECT COUNT(DISTINCT source_row_id) FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_ledger_ce8978f61503ea9e13b8553698b719af`) = @source_rows
  AS 'Source ledger contains duplicate row IDs';
ASSERT NOT EXISTS (
  SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_ledger_ce8978f61503ea9e13b8553698b719af` WHERE run_id <> @run_id OR source_fingerprint <> @fingerprint
    OR disposition NOT IN ('clean', 'quarantine')
) AS 'Unexpected ledger identity or disposition';
ASSERT (SELECT COUNT(*) FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_clean_ce8978f61503ea9e13b8553698b719af`) = @clean_rows AS 'Clean count mismatch';
ASSERT (SELECT COUNT(*) FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quarantine_ce8978f61503ea9e13b8553698b719af`) = @quarantined_rows AS 'Quarantine count mismatch';
ASSERT (SELECT COUNT(*) FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quality_ce8978f61503ea9e13b8553698b719af`) = @quality_rows AS 'Quality count mismatch';
ASSERT @clean_rows + @quarantined_rows = @source_rows AS 'Routing counts mismatch';
ASSERT NOT EXISTS (
  SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_clean_ce8978f61503ea9e13b8553698b719af` WHERE run_id <> @run_id OR source_fingerprint <> @fingerprint
  UNION ALL
  SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quarantine_ce8978f61503ea9e13b8553698b719af` WHERE run_id <> @run_id OR source_fingerprint <> @fingerprint
  UNION ALL
  SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quality_ce8978f61503ea9e13b8553698b719af` WHERE run_id <> @run_id OR source_fingerprint <> @fingerprint
) AS 'Unexpected staged identity';
ASSERT (SELECT COUNT(DISTINCT check_name) FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quality_ce8978f61503ea9e13b8553698b719af`) = @quality_rows
  AS 'Duplicate quality checks';
ASSERT NOT EXISTS (
  SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quality_ce8978f61503ea9e13b8553698b719af`
  WHERE evaluated_rows <> @source_rows OR failed_rows < 0 OR failed_rows > evaluated_rows
     OR passed <> (failed_rows = 0)
) AS 'Invalid quality counters';
ASSERT NOT EXISTS (
  SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quarantine_ce8978f61503ea9e13b8553698b719af`
  WHERE ARRAY_LENGTH(error_codes) = 0
     OR LOWER(TO_HEX(SHA256(raw_payload))) <> source_record_sha256
) AS 'Invalid quarantine evidence';

IF NOT EXISTS (SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.pipeline_runs` WHERE run_id = @run_id) THEN
  ASSERT NOT EXISTS (
    SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.clean_transactions` WHERE run_id = @run_id
    UNION ALL
    SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.quarantined_records` WHERE run_id = @run_id
    UNION ALL
    SELECT 1 FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.quality_results` WHERE run_id = @run_id
  ) AS 'Uncommitted target rows require investigation';
  INSERT INTO `gcp-intelligent-data-quality.synthetic_quality_lakehouse.clean_transactions` SELECT * FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_clean_ce8978f61503ea9e13b8553698b719af`;
  INSERT INTO `gcp-intelligent-data-quality.synthetic_quality_lakehouse.quarantined_records` SELECT * FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quarantine_ce8978f61503ea9e13b8553698b719af`;
  INSERT INTO `gcp-intelligent-data-quality.synthetic_quality_lakehouse.quality_results` SELECT * FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_quality_ce8978f61503ea9e13b8553698b719af`;
  INSERT INTO `gcp-intelligent-data-quality.synthetic_quality_lakehouse.pipeline_runs`
    VALUES (@run_id, @fingerprint, @source_rows, @clean_rows, @quarantined_rows,
            @quality_rows, @source_uri, @source_generation, @source_sha256, CURRENT_TIMESTAMP());
END IF;

ASSERT ((SELECT source_rows = @source_rows AND target_rows = @source_rows AND source_duplicates = 0 AND target_duplicates = 0 AND mismatched_rows = 0 FROM (-- Run-scoped row identity, disposition, payload hash and amount reconciliation.
WITH targets AS (
  SELECT source_row_id, source_record_sha256, source_fingerprint,
         'clean' AS disposition, transaction_amount_usd AS amount_usd
  FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.clean_transactions` WHERE run_id = @run_id
  UNION ALL
  SELECT source_row_id, source_record_sha256, source_fingerprint,
         'quarantine' AS disposition, CAST(NULL AS FLOAT64) AS amount_usd
  FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.quarantined_records` WHERE run_id = @run_id
), source AS (
  SELECT * FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.stg_ledger_ce8978f61503ea9e13b8553698b719af` WHERE run_id = @run_id
), mismatches AS (
  SELECT s.source_row_id AS source_id, t.source_row_id AS target_id
  FROM source s FULL OUTER JOIN targets t USING (source_row_id)
  WHERE s.source_row_id IS NULL OR t.source_row_id IS NULL
     OR s.source_record_sha256 <> t.source_record_sha256
     OR s.source_fingerprint <> t.source_fingerprint
     OR s.disposition <> t.disposition
     OR ABS(COALESCE(s.amount_usd, 0) - COALESCE(t.amount_usd, 0)) > 0.000001
)
SELECT
  (SELECT COUNT(*) FROM source) AS source_rows,
  (SELECT COUNT(*) FROM targets) AS target_rows,
  (SELECT COUNT(*) - COUNT(DISTINCT source_row_id) FROM source) AS source_duplicates,
  (SELECT COUNT(*) - COUNT(DISTINCT source_row_id) FROM targets) AS target_duplicates,
  (SELECT COUNT(*) FROM mismatches) AS mismatched_rows
)) ) AS 'Source-to-target reconciliation failed';
ASSERT (SELECT COUNT(*) FROM `gcp-intelligent-data-quality.synthetic_quality_lakehouse.quality_results` WHERE run_id = @run_id) = @quality_rows
  AS 'Published quality count mismatch';
COMMIT TRANSACTION;
